mapper.select:





/* selectReqList - Lee MS */       
    B.INCDNT_TTL_NM AS INCDNT_TTL_NM,               /* 사건제목명 */ 
    B.INCDNT_OCRN_YMD AS INCDNT_OCRN_YMD,           /* 사건발생일자 */
    A.EMRG_CNTRMS_TRMN_YMD AS EMRG_CNTRMS_TRMN_YMD, /* 종결일자 */
    C##RG.DEC_B64(D.FLNM_ENCPT) AS PIC_NM,       /* 담당자명 */
    C.INST_NM AS INST_NM,                           /* 기관명 */
    A.EMRG_CNTRMS_INCDNT_NO AS EMRG_CNTRMS_INCDNT_NO, /*긴급대응사건번호 */
    A.EMRG_CNTRMS_TRMN_NO AS EMRG_CNTRMS_TRMN_NO    /*긴급대응종결번호 */
FROM ACA720 A, ACA700 B, SAA000 C, SCA100 D  /* 통합기관(C), 종사사(D)  */
WHERE A.EMRG_CNTRMS_INCDNT_NO = B.EMRG_CNTRMS_INCDNT_NO
AND A.INST_NO = C.INST_NO
AND A.PIC_NO = D.ENFSN_NO
AND A.EMRG_CNTRMS_TRMN_YMD >= #{BGNG_YMD}
AND A.EMRG_CNTRMS_TRMN_YMD <= #{END_YMD}
AND B.INCDNT_TTL_NM LIKE '%'||#{INCDNT_TTL_NM}||'%'



    AND C##RG.DEC_B64(D.FLNM_ENCPT) LIKE '%'||#{PIC_NM}||'%'


   /* 상담복지센터는 모두 조회 */  
    /* 20230410_권한 쿼리_권한쿼리시작*/                               

    /* 20230220_권한 쿼리_권한쿼리종료*/


ORDER BY A.EMRG_CNTRMS_TRMN_YMD DESC

/* selectReqById - Lee MS */
SELECT B.EMRG_CNTRMS_INCDNT_LCLAS_SE_CD AS EMRG_CNTRMS_INCDNT_LCLAS_SE_CD, /* 긴급대응사건대분류구분코드 */ B.EMRG_CNTRMS_INCDNT_MLSFC_SE_CD AS EMRG_CNTRMS_INCDNT_MLSFC_SE_CD, /* 긴급대응사건중분류구분코드 */ B.EMRG_CNTRMS_INCDNT_SCLAS_SE_CD AS EMRG_CNTRMS_INCDNT_SCLAS_SE_CD, /* 긴급대응사건소분류구분코드 */ B.INCDNT_TTL_NM AS INCDNT_TTL_NM, /* 사건제목명 */ B.INCDNT_OCRN_YMD AS INCDNT_OCRN_YMD, /* 사건발생일자 */ B.OCRN_RPT_YMD AS OCRN_RPT_YMD, /* 발생보고일자 */ B.INCDNT_CN AS INCDNT_CN, /* 사건내용 */ B.INCDNT_RELATA_SCALE_CN AS INCDNT_RELATA_SCALE_CN, /* 사건관련규모내용 */
C##RG.DEC_B64(E.FLNM_ENCPT) AS PIC_NM, /* 담당자명 */ E.WRD_TELNO AS WRD_TELNO, /* 유선전화번호 */ C##RG.DEC_B64(E.MBL_TELNO_ENCPT) AS MBL_TELNO, /* 휴대전화번호 */ C##RG.DEC_B64(E.EML_ADDR_ENCPT) AS EML_ADDR, /* 이메일 */ F.CTPV_NM AS CTPV_NM, /* 시도명 */ F.SGG_NM AS SGG_NM, /* 시군구명 */ B.ATFINO AS ATFINO, /* 첨부화일번호 */ B.RM_CN AS RM_CN, /* 비고내용 */
A.EMRG_CNTRMS_TRMN_YMD AS EMRG_CNTRMS_TRMN_YMD, /* 긴급대응종결일자 */ A.GNRLZ_OPNN_CN AS GNRLZ_OPNN_CN, /* 종합의견내용 */ A.AFTFCT_MNG_PLAN_CN AS AFTFCT_MNG_PLAN_CN, /* 사후관리계획내용 */ A.PIC_NO AS PIC_NO, /* 담당자번호 */ A.INST_NO AS INST_NO, /* 기관번호 */
A.EMRG_CNTRMS_TRMN_NO AS EMRG_CNTRMS_TRMN_NO, /* 긴급대응종결번호 */ A.EMRG_CNTRMS_INCDNT_NO AS EMRG_CNTRMS_INCDNT_NO /* 긴급대응사건번호 */ FROM ACA720 A, ACA700 B, SAA000 D, SCA100 E, SAA020 F /* 긴급대응보고(C) 통합기관(D), 종사자(E) 시군구코드(F) */ WHERE A.EMRG_CNTRMS_INCDNT_NO = B.EMRG_CNTRMS_INCDNT_NO AND B.INST_NO = D.INST_NO AND D.SGG_CD = F.SGG_CD(+) AND B.PIC_NO = E.ENFSN_NO AND A.EMRG_CNTRMS_TRMN_NO = #{EMRG_CNTRMS_TRMN_NO}

mapper.delete:

 /* deleteData - Lee  MS */

DELETE FROM ACA720 /* 긴급대응종결 */
WHERE EMRG_CNTRMS_TRMN_NO = #{EMRG_CNTRMS_TRMN_NO}
